def baseline_forward(model, batch: Dict[str, torch.Tensor]):
    """Forward pass bypassing SmolVLAPolicy.forward()'s action_is_pad masking bug.

    Calls VLAFlowMatching.forward() directly, slices to actual action_dim=14.
    """
    vla = model.model if hasattr(model, "model") else model
    output = vla.forward(batch)
    loss_all = output["loss"]
    action_pred = output.get("action", None)
    if action_pred is not None and action_pred.shape[-1] > 14:
        actions_gt = batch["action"][:, :, :14]
        action_pred_14 = action_pred[:, :, :14]
        loss_all = F.mse_loss(action_pred_14, actions_gt)
    grad_norm = torch.tensor(0.0)
    return loss_all, grad_norm


def _find_connector(model):
    """Find the multi_modal_projector (pixel shuffle connector) in SmolVLA."""
    for name, module in model.named_modules():
        if "multi_modal_projector" in name:
            children = list(module.children())
            if not children:
                return module
            return module
    return None


def _apply_random_pruning_hook(model, pruning_ratio: float, seed: int, batch_idx: int):
    """Register a forward hook for random visual token pruning. Returns hook handle."""
    n_visual = 64
    k_keep = int(n_visual * (1 - pruning_ratio))

    def hook_fn(module, input, output):
        if isinstance(output, tuple):
            tokens = output[0]
        else:
            tokens = output
        if tokens.dim() != 3 or tokens.shape[1] < n_visual:
            return output
        B = tokens.shape[0]
        g = torch.Generator(device="cpu")
        g.manual_seed(seed + batch_idx)
        mask = torch.zeros(B, tokens.shape[1], device=tokens.device)
        for b in range(B):
            perm = torch.randperm(tokens.shape[1], generator=g, device="cpu")[:k_keep]
            mask[b, perm] = 1.0
        masked = tokens * mask.unsqueeze(-1)
        if isinstance(output, tuple):
            return (masked,) + output[1:]
        return masked

    connector = _find_connector(model)
    if connector is None:
        log.warning("Could not find multi_modal_projector for random pruning")
        return None
    return connector.register_forward_hook(hook_fn)
